   String ext="/data/media/0/Android/data/"+pkg+"/files";e.run(e.job(),"mkdir -p "+BackupEngine.q(ext)+"\nprintf 'original external marker' > "+BackupEngine.q(ext+"/marker")+"\n",false);
   Uri tree=SetupActivity.folder(c);folder=DocumentsContract.createDocument(c.getContentResolver(),DocumentsContract.buildDocumentUriUsingTree(tree,DocumentsContract.getTreeDocumentId(tree)),DocumentsContract.Document.MIME_TYPE_DIR,"Raven-single-pass-disposable-"+UUID.randomUUID());require(folder!=null,"folder");e.backupApks=true;e.backupExternal=true;e.backupOne(Collections.singletonList(pkg),tree,folder);
